Translate the following MS C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
using namespace std;

double abs_value(double val) {
    return (val < 0) ? -val : val;
}

int main() {
    int x, y, n;
    cin >> x >> y >> n;
    int best_num = 0, best_den = 1;
    double best_diff = 1e15;
    double target = static_cast<double>(x) / y;

    for (int denom = 1; denom <= n; ++denom) {
        int left_bound = 0, right_bound = 1000000000;
        while (right_bound - left_bound > 10) {
            int m1 = left_bound + (right_bound - left_bound) / 3;
            int m2 = right_bound - (right_bound - left_bound) / 3;
            double diff1 = abs_value(target - static_cast<double>(m1) / denom);
            double diff2 = abs_value(target - static_cast<double>(m2) / denom);
            if (diff1 > diff2)
                left_bound = m1;
            else
                right_bound = m2;
        }
        for (int i = left_bound; i <= right_bound + 3; ++i) {
            double current_diff = abs_value(target - static_cast<double>(i) / denom);
            if (current_diff < best_diff - 1e-15) {
                best_diff = current_diff;
                best_num = i;
                best_den = denom;
            }
        }
    }
    cout << best_num << '/' << best_den;
    return 0;
}
